FUNCTION_BLOCK FB_MarineAzipod_VectorCavitation
(* ============================================================================
   LUMINA HIGH-INTEGRITY CYBER-PHYSICAL AUTOMATION ENGINE
   IEC 61131-3 COMPLIANT FUNCTION BLOCK
   SYSTEM: PODDED AZIMUTH PROPULSOR DYNAMIC VECTORING & CAVITATION PROTECTION
   AUTHOR: Principal Automation Fellow & Cyber-Physical Systems Chair (75+ Yr Persona)
   CLASSIFICATION: DNV-GL Pt.4 Ch.5 / Marine Dynamic Positioning DP-3 Redundant
   ============================================================================
   FUNCTION BLOCK ARCHITECTURE:
   1. 2oo3 Triple Modular Redundancy (TMR) voting with dynamic disparity tracking
      for shaft rotational velocity, azimuth steering angle, and hydro-acoustic noise.
   2. Real-time hydrodynamic cavitation inception boundary evaluation using
      thermodynamic vapor pressure (Antoine equation), local hydrostatic head at
      propeller tip disc immersion, and advance velocity inflow angle of attack.
   3. Constrained dynamic vectoring model predictive controller (MPC) allocating
      optimal azimuth rate-of-turn and shaft torque demand while enforcing
      envelope protection against blade suction-side sheet and tip-vortex cavitation.
   4. Multi-level graceful degradation state machine with dual-bank hydraulic
      isolation, synthetic analytical observers, and longitudinal park sequencing.
   ============================================================================ *)

VAR_INPUT
    bEnable                 : BOOL;     (* System master enable permissive signal [-] *)
    bEStop                  : BOOL;     (* Emergency stop circuit OK (Active HIGH = Normal, LOW = Trip) [-] *)
    bAckAlarms              : BOOL;     (* Alarm manual acknowledge push-button [-] *)
    rThrustDemand_kN        : REAL;     (* Dynamic Positioning commanded thrust vector magnitude [0.0..1200.0 kN] *)
    rAzimuthDemand_deg      : REAL;     (* DP commanded azimuth angle setpoint [-180.0..+180.0 deg] *)
    rVesselSpeed_knots      : REAL;     (* Hull longitudinal surge speed through water [0.0..35.0 knots] *)
    rVesselDriftAngle_deg   : REAL;     (* Hydrodynamic drift / leeway angle of hull [-45.0..+45.0 deg] *)
    rShaftSpeed_RPM_A       : REAL;     (* Propeller shaft optical pulse tachometer Channel A [0.0..220.0 rpm] *)
    rShaftSpeed_RPM_B       : REAL;     (* Propeller shaft magnetic pickup tachometer Channel B [0.0..220.0 rpm] *)
    rShaftSpeed_RPM_C       : REAL;     (* Propeller shaft resolver derived speed Channel C [0.0..220.0 rpm] *)
    rAzimuthAngle_deg_A     : REAL;     (* Absolute optical slew ring encoder Channel A [-180.0..+180.0 deg] *)
    rAzimuthAngle_deg_B     : REAL;     (* Multi-turn inductive slew ring encoder Channel B [-180.0..+180.0 deg] *)
    rAzimuthAngle_deg_C     : REAL;     (* Geared feedback resolver Channel C [-180.0..+180.0 deg] *)
    rSteeringRate_deg_s     : REAL;     (* Measured angular rate-of-turn of azimuth housing [-12.0..+12.0 deg/s] *)
    rHydraulicPressure_A_bar: REAL;     (* Dual-ram steering hydraulic supply pressure Bank A [0.0..350.0 bar] *)
    rHydraulicPressure_B_bar: REAL;     (* Dual-ram steering hydraulic supply pressure Bank B [0.0..350.0 bar] *)
    rHydroAcoustic_dB_A     : REAL;     (* Hull-mounted piezoelectric hydrophone cavitation sensor A [80.0..190.0 dB] *)
    rHydroAcoustic_dB_B     : REAL;     (* Hull-mounted piezoelectric hydrophone cavitation sensor B [80.0..190.0 dB] *)
    rHydroAcoustic_dB_C     : REAL;     (* Hull-mounted piezoelectric hydrophone cavitation sensor C [80.0..190.0 dB] *)
    rPropellerDraftDepth_m  : REAL;     (* Propeller shaft centerline waterline submergence [3.5..12.0 m] *)
    rSeawaterTemp_degC      : REAL;     (* Ambient sea surface temperature [-2.0..+38.0 deg C] *)
    rCycleTime_s            : REAL;     (* Deterministic PLC execution scan cycle time [e.g. 0.010 s] *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* Propulsor ready for autonomous dynamic thrust allocation [-] *)
    rShaftSpeedCommand_RPM  : REAL;     (* Modulated setpoint transmitted to propulsion VFD inverter [0.0..220.0 rpm] *)
    rAzimuthAngleCommand_deg: REAL;     (* Modulated slew angle setpoint to hydraulic steering valves [-180.0..+180.0 deg] *)
    rDeliveredThrust_kN     : REAL;     (* Hydrodynamically estimated actual net delivered thrust [0.0..1200.0 kN] *)
    rCavitationIndex_Sigma  : REAL;     (* Real-time dimensionless Thoma-Keller cavitation inception number [-] *)
    rCavitationMargin_pct   : REAL;     (* Safety headroom above critical cavitation boundary [-100.0..+100.0 %] *)
    rCavitationRiskFactor   : REAL;     (* Normalized cavitation severity index [0.0 = Safe, 1.0 = Severe Inception] *)
    wSystemStatusWord       : WORD;     (* Packed bitfield reflecting operating regime and health metrics *)
    wAlarmWord              : WORD;     (* Packed bitfield of prioritized critical safety and sensor trip conditions *)
    bCavitationActive       : BOOL;     (* Active acoustic/thermodynamic cavitation inception mitigation active [-] *)
    bDegradedMode           : BOOL;     (* Operating under reduced hydraulic capacity or degraded sensor redundancy [-] *)
END_VAR

VAR
    (* -------------------------------------------------------------------------
       HYDRODYNAMIC PROPELLER & FLUID PHYSICAL CONSTANTS
       ------------------------------------------------------------------------- *)
    rRhoSeawater            : REAL := 1025.0;       (* Standard seawater density [kg/m^3] *)
    rGravity                : REAL := 9.80665;      (* Standard acceleration of gravity [m/s^2] *)
    rAtmosphericPressure_Pa : REAL := 101325.0;     (* Standard atmospheric surface pressure [Pa] *)
    rPropDiameter_m         : REAL := 3.80;         (* Four-bladed Kaplan-type propeller diameter [m] *)
    rPropDiskArea_m2        : REAL := 11.3411;      (* Disc area: Pi/4 * D^2 [m^2] *)
    rPropPitchRatio_PD      : REAL := 1.15;         (* Propeller nominal pitch-to-diameter ratio [-] *)
    rWakeFraction_w         : REAL := 0.14;         (* Hull nominal wake fraction [-] *)
    rThrustDeduction_t      : REAL := 0.12;         (* Hull thrust deduction factor [-] *)

    (* -------------------------------------------------------------------------
       2oo3 TRIPLE MODULAR REDUNDANCY (TMR) INTERNAL ARBITRATION REGISTERS
       ------------------------------------------------------------------------- *)
    rVotedShaftSpeed_RPM    : REAL;                 (* Synthesized consensus shaft rotational speed [rpm] *)
    rVotedAzimuthAngle_deg  : REAL;                 (* Synthesized consensus azimuth angle [deg] *)
    rVotedAcousticNoise_dB  : REAL;                 (* Synthesized consensus cavitation hydro-acoustic emission [dB] *)
    bSpeedSensorFault_A     : BOOL;                 (* Tachometer channel A disparity latch *)
    bSpeedSensorFault_B     : BOOL;                 (* Tachometer channel B disparity latch *)
    bSpeedSensorFault_C     : BOOL;                 (* Tachometer channel C disparity latch *)
    bAngleSensorFault_A     : BOOL;                 (* Slew encoder channel A disparity latch *)
    bAngleSensorFault_B     : BOOL;                 (* Slew encoder channel B disparity latch *)
    bAngleSensorFault_C     : BOOL;                 (* Slew encoder channel C disparity latch *)
    bAcousticSensorFault_A  : BOOL;                 (* Hydrophone channel A disparity latch *)
    bAcousticSensorFault_B  : BOOL;                 (* Hydrophone channel B disparity latch *)
    bAcousticSensorFault_C  : BOOL;                 (* Hydrophone channel C disparity latch *)

    (* TMR Disparity Persistence Timers *)
    rSpeedDisparityTimer_A  : REAL;
    rSpeedDisparityTimer_B  : REAL;
    rSpeedDisparityTimer_C  : REAL;
    rAngleDisparityTimer_A  : REAL;
    rAngleDisparityTimer_B  : REAL;
    rAngleDisparityTimer_C  : REAL;

    (* -------------------------------------------------------------------------
       STATE MACHINE ENUMERATION & SEQUENCING
       ------------------------------------------------------------------------- *)
    iOperatingState         : INT := 0;             (* 0=INIT, 10=TMR_CHECK, 20=DP_VECTOR, 30=TRANSIT, 40=CAV_MITIGATE, 50=DEGRADED_HYDR, 60=SENSOR_FALLBACK, 99=TRIP *)
    iPreviousState          : INT := -1;
    rStateTimer_s           : REAL := 0.0;          (* Dwell timer in active state [s] *)

    (* -------------------------------------------------------------------------
       CAVITATION DYNAMICS & THERMODYNAMIC INCEPTION ESTIMATOR
       ------------------------------------------------------------------------- *)
    rVaporPressure_Pa       : REAL;                 (* Water vapor saturation pressure via Antoine equation [Pa] *)
    rTipSubmergence_m       : REAL;                 (* Instantaneous immersion depth of top blade tip [m] *)
    rStaticPressureTip_Pa   : REAL;                 (* Local absolute static pressure at top blade tip [Pa] *)
    rAdvanceSpeed_ms        : REAL;                 (* Effective axial water inflow velocity to propulsor [m/s] *)
    rInflowAngle_deg        : REAL;                 (* Angle of attack between inflow vector and pod heading [deg] *)
    rTipSpeed_ms            : REAL;                 (* Blade tip resultant circumferential & axial velocity [m/s] *)
    rDynamicPressure_Pa     : REAL;                 (* Dynamic head: 0.5 * rho * V_tip^2 [Pa] *)
    rThrustLoading_CT       : REAL;                 (* Non-dimensional thrust loading coefficient [-] *)
    rCriticalSigma          : REAL;                 (* Dynamic cavitation inception threshold parameter [-] *)
    rAcousticCavitationScore: REAL;                 (* Normalized hydrophone energy score above baseline [0.0..1.0] *)

    (* -------------------------------------------------------------------------
       MODEL PREDICTIVE VECTORING RATE LIMITERS & SMOOTHING FILTERS
       ------------------------------------------------------------------------- *)
    rFilteredAzimuthCmd_deg : REAL;                 (* Rate-limited dynamic vectoring command [deg] *)
    rFilteredRPMCmd         : REAL;                 (* Acceleration-limited VFD setpoint [rpm] *)
    rMaxSlewRate_deg_s      : REAL;                 (* Dynamically permitted azimuth angular velocity [deg/s] *)
    rMaxRPMRate_RPM_s       : REAL;                 (* Dynamically permitted shaft acceleration [rpm/s] *)
    rSlewDelta              : REAL;                 (* Angular increment per execution scan [deg] *)
    rRPMDelta               : REAL;                 (* Rotational speed increment per execution scan [rpm] *)
    rHydraulicTorqueMargin  : REAL;                 (* Calculated hydraulic steering reserve factor [0.0..1.0] *)

    (* -------------------------------------------------------------------------
       TEMPORARY ARBITRATION & NUMERICAL CALCULATION REGISTERS
       ------------------------------------------------------------------------- *)
    rDiffAB                 : REAL;
    rDiffBC                 : REAL;
    rDiffCA                 : REAL;
    rAbsA                   : REAL;
    rAbsB                   : REAL;
    rAbsC                   : REAL;
    rMinThrustRequired_kN   : REAL;
    rKT_AdvanceRatio        : REAL;                 (* Wageningen B-series advance coefficient J *)
    rEstimatedKT            : REAL;                 (* Open water thrust coefficient Kt *)
    bHydraulicHealthy_A     : BOOL;
    bHydraulicHealthy_B     : BOOL;
END_VAR

(* === MAIN EXECUTION LOGIC === *)

(* -----------------------------------------------------------------------------
   PHASE 1: HARDWARE SAFETY & EMERGENCY STOP SUPERVISION
   ----------------------------------------------------------------------------- *)
IF NOT bEStop THEN
    iOperatingState := 99; (* Force immediate transition to fail-safe park/shutdown *)
    wAlarmWord := wAlarmWord OR 16#0001; (* Bit 0: Emergency Stop Loop Tripped *)
END_IF;

IF bAckAlarms THEN
    (* Mask latchable transient alarms if permissive condition is restored *)
    IF bEStop THEN
        wAlarmWord := wAlarmWord AND 16#FFFE;
    END_IF;
    IF bSpeedSensorFault_A AND (ABS(rShaftSpeed_RPM_A - rShaftSpeed_RPM_B) < 5.0) THEN
        bSpeedSensorFault_A := FALSE;
        wAlarmWord := wAlarmWord AND 16#FFFD; (* Clear Bit 1 *)
    END_IF;
    IF bAngleSensorFault_A AND (ABS(rAzimuthAngle_deg_A - rAzimuthAngle_deg_B) < 2.0) THEN
        bAngleSensorFault_A := FALSE;
        wAlarmWord := wAlarmWord AND 16#FFF7; (* Clear Bit 3 *)
    END_IF;
END_IF;

(* -----------------------------------------------------------------------------
   PHASE 2: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) SENSOR VOTING ALGORITHMS
   ----------------------------------------------------------------------------- *)

(* 2.1: Shaft Speed (RPM) 2oo3 Disparity Detection & Arbitration *)
rDiffAB := ABS(rShaftSpeed_RPM_A - rShaftSpeed_RPM_B);
rDiffBC := ABS(rShaftSpeed_RPM_B - rShaftSpeed_RPM_C);
rDiffCA := ABS(rShaftSpeed_RPM_C - rShaftSpeed_RPM_A);

(* Disparity integration against 8.0 RPM deviation limit *)
IF (rDiffAB > 8.0) AND (rDiffCA > 8.0) THEN
    rSpeedDisparityTimer_A := rSpeedDisparityTimer_A + rCycleTime_s;
    IF rSpeedDisparityTimer_A > 0.25 THEN
        bSpeedSensorFault_A := TRUE;
        wAlarmWord := wAlarmWord OR 16#0002; (* Bit 1: Speed Sensor A Disparity Fail *)
    END_IF;
ELSE
    rSpeedDisparityTimer_A := MAX(0.0, rSpeedDisparityTimer_A - rCycleTime_s);
END_IF;

IF (rDiffAB > 8.0) AND (rDiffBC > 8.0) THEN
    rSpeedDisparityTimer_B := rSpeedDisparityTimer_B + rCycleTime_s;
    IF rSpeedDisparityTimer_B > 0.25 THEN
        bSpeedSensorFault_B := TRUE;
        wAlarmWord := wAlarmWord OR 16#0004; (* Bit 2: Speed Sensor B Disparity Fail *)
    END_IF;
ELSE
    rSpeedDisparityTimer_B := MAX(0.0, rSpeedDisparityTimer_B - rCycleTime_s);
END_IF;

IF (rDiffBC > 8.0) AND (rDiffCA > 8.0) THEN
    rSpeedDisparityTimer_C := rSpeedDisparityTimer_C + rCycleTime_s;
    IF rSpeedDisparityTimer_C > 0.25 THEN
        bSpeedSensorFault_C := TRUE;
        wAlarmWord := wAlarmWord OR 16#0008; (* Bit 3: Speed Sensor C Disparity Fail *)
    END_IF;
ELSE
    rSpeedDisparityTimer_C := MAX(0.0, rSpeedDisparityTimer_C - rCycleTime_s);
END_IF;

(* 2oo3 Median Selection Logic *)
IF (NOT bSpeedSensorFault_A) AND (NOT bSpeedSensorFault_B) AND (NOT bSpeedSensorFault_C) THEN
    (* All channels healthy: extract exact median *)
    IF ((rShaftSpeed_RPM_A >= rShaftSpeed_RPM_B) AND (rShaftSpeed_RPM_A <= rShaftSpeed_RPM_C)) OR
       ((rShaftSpeed_RPM_A <= rShaftSpeed_RPM_B) AND (rShaftSpeed_RPM_A >= rShaftSpeed_RPM_C)) THEN
        rVotedShaftSpeed_RPM := rShaftSpeed_RPM_A;
    ELSIF ((rShaftSpeed_RPM_B >= rShaftSpeed_RPM_A) AND (rShaftSpeed_RPM_B <= rShaftSpeed_RPM_C)) OR
          ((rShaftSpeed_RPM_B <= rShaftSpeed_RPM_A) AND (rShaftSpeed_RPM_B >= rShaftSpeed_RPM_C)) THEN
        rVotedShaftSpeed_RPM := rShaftSpeed_RPM_B;
    ELSE
        rVotedShaftSpeed_RPM := rShaftSpeed_RPM_C;
    END_IF;
ELSIF bSpeedSensorFault_A AND (NOT bSpeedSensorFault_B) AND (NOT bSpeedSensorFault_C) THEN
    rVotedShaftSpeed_RPM := 0.5 * (rShaftSpeed_RPM_B + rShaftSpeed_RPM_C);
ELSIF bSpeedSensorFault_B AND (NOT bSpeedSensorFault_A) AND (NOT bSpeedSensorFault_C) THEN
    rVotedShaftSpeed_RPM := 0.5 * (rShaftSpeed_RPM_A + rShaftSpeed_RPM_C);
ELSIF bSpeedSensorFault_C AND (NOT bSpeedSensorFault_A) AND (NOT bSpeedSensorFault_B) THEN
    rVotedShaftSpeed_RPM := 0.5 * (rShaftSpeed_RPM_A + rShaftSpeed_RPM_B);
ELSE
    (* Multiple failures: isolate and fallback to last known command *)
    rVotedShaftSpeed_RPM := rFilteredRPMCmd;
    wAlarmWord := wAlarmWord OR 16#0010; (* Bit 4: Total Speed Feedback Loss *)
END_IF;

(* 2.2: Azimuth Slew Angle 2oo3 Disparity Detection & Arbitration *)
(* Cyclic angle distance wrapping over [-180..+180] domain *)
rDiffAB := rAzimuthAngle_deg_A - rAzimuthAngle_deg_B;
WHILE rDiffAB > 180.0 DO rDiffAB := rDiffAB - 360.0; END_WHILE;
WHILE rDiffAB < -180.0 DO rDiffAB := rDiffAB + 360.0; END_WHILE;
rDiffAB := ABS(rDiffAB);

rDiffBC := rAzimuthAngle_deg_B - rAzimuthAngle_deg_C;
WHILE rDiffBC > 180.0 DO rDiffBC := rDiffBC - 360.0; END_WHILE;
WHILE rDiffBC < -180.0 DO rDiffBC := rDiffBC + 360.0; END_WHILE;
rDiffBC := ABS(rDiffBC);

rDiffCA := rAzimuthAngle_deg_C - rAzimuthAngle_deg_A;
WHILE rDiffCA > 180.0 DO rDiffCA := rDiffCA - 360.0; END_WHILE;
WHILE rDiffCA < -180.0 DO rDiffCA := rDiffCA + 360.0; END_WHILE;
rDiffCA := ABS(rDiffCA);

IF (rDiffAB > 3.0) AND (rDiffCA > 3.0) THEN
    rAngleDisparityTimer_A := rAngleDisparityTimer_A + rCycleTime_s;
    IF rAngleDisparityTimer_A > 0.20 THEN
        bAngleSensorFault_A := TRUE;
        wAlarmWord := wAlarmWord OR 16#0020; (* Bit 5: Angle Sensor A Disparity Fail *)
    END_IF;
ELSE
    rAngleDisparityTimer_A := MAX(0.0, rAngleDisparityTimer_A - rCycleTime_s);
END_IF;

IF (rDiffAB > 3.0) AND (rDiffBC > 3.0) THEN
    rAngleDisparityTimer_B := rAngleDisparityTimer_B + rCycleTime_s;
    IF rAngleDisparityTimer_B > 0.20 THEN
        bAngleSensorFault_B := TRUE;
        wAlarmWord := wAlarmWord OR 16#0040; (* Bit 6: Angle Sensor B Disparity Fail *)
    END_IF;
ELSE
    rAngleDisparityTimer_B := MAX(0.0, rAngleDisparityTimer_B - rCycleTime_s);
END_IF;

IF (rDiffBC > 3.0) AND (rDiffCA > 3.0) THEN
    rAngleDisparityTimer_C := rAngleDisparityTimer_C + rCycleTime_s;
    IF rAngleDisparityTimer_C > 0.20 THEN
        bAngleSensorFault_C := TRUE;
        wAlarmWord := wAlarmWord OR 16#0080; (* Bit 7: Angle Sensor C Disparity Fail *)
    END_IF;
ELSE
    rAngleDisparityTimer_C := MAX(0.0, rAngleDisparityTimer_C - rCycleTime_s);
END_IF;

(* 2oo3 Angle Consensus Selection *)
IF (NOT bAngleSensorFault_A) AND (NOT bAngleSensorFault_B) AND (NOT bAngleSensorFault_C) THEN
    IF ((rAzimuthAngle_deg_A >= rAzimuthAngle_deg_B) AND (rAzimuthAngle_deg_A <= rAzimuthAngle_deg_C)) OR
       ((rAzimuthAngle_deg_A <= rAzimuthAngle_deg_B) AND (rAzimuthAngle_deg_A >= rAzimuthAngle_deg_C)) THEN
        rVotedAzimuthAngle_deg := rAzimuthAngle_deg_A;
    ELSIF ((rAzimuthAngle_deg_B >= rAzimuthAngle_deg_A) AND (rAzimuthAngle_deg_B <= rAzimuthAngle_deg_C)) OR
          ((rAzimuthAngle_deg_B <= rAzimuthAngle_deg_A) AND (rAzimuthAngle_deg_B >= rAzimuthAngle_deg_C)) THEN
        rVotedAzimuthAngle_deg := rAzimuthAngle_deg_B;
    ELSE
        rVotedAzimuthAngle_deg := rAzimuthAngle_deg_C;
    END_IF;
ELSIF bAngleSensorFault_A AND (NOT bAngleSensorFault_B) AND (NOT bAngleSensorFault_C) THEN
    rVotedAzimuthAngle_deg := 0.5 * (rAzimuthAngle_deg_B + rAzimuthAngle_deg_C);
ELSIF bAngleSensorFault_B AND (NOT bAngleSensorFault_A) AND (NOT bAngleSensorFault_C) THEN
    rVotedAzimuthAngle_deg := 0.5 * (rAzimuthAngle_deg_A + rAzimuthAngle_deg_C);
ELSIF bAngleSensorFault_C AND (NOT bAngleSensorFault_A) AND (NOT bAngleSensorFault_B) THEN
    rVotedAzimuthAngle_deg := 0.5 * (rAzimuthAngle_deg_A + rAzimuthAngle_deg_B);
ELSE
    rVotedAzimuthAngle_deg := rFilteredAzimuthCmd_deg;
    wAlarmWord := wAlarmWord OR 16#0100; (* Bit 8: Total Azimuth Angle Feedback Loss *)
END_IF;

(* 2.3: Hydro-Acoustic Noise 2oo3 Voting *)
rVotedAcousticNoise_dB := MAX(rHydroAcoustic_dB_A, MAX(rHydroAcoustic_dB_B, rHydroAcoustic_dB_C));
IF rVotedAcousticNoise_dB > 145.0 THEN
    rAcousticCavitationScore := MIN(1.0, (rVotedAcousticNoise_dB - 145.0) / 35.0);
ELSE
    rAcousticCavitationScore := 0.0;
END_IF;

(* -----------------------------------------------------------------------------
   PHASE 3: HYDRODYNAMIC CAVITATION INCEPTION EVALUATION MODEL
   ----------------------------------------------------------------------------- *)
(* Antoine Saturation Vapor Pressure Model for Seawater [Pa] *)
rVaporPressure_Pa := 610.78 * EXP((17.27 * rSeawaterTemp_degC) / (rSeawaterTemp_degC + 237.3));

(* Hydrostatic Head at Upper Blade Tip Immersion (Worst-case minimum pressure point) *)
rTipSubmergence_m := MAX(1.0, rPropellerDraftDepth_m - (0.5 * rPropDiameter_m));
rStaticPressureTip_Pa := rAtmosphericPressure_Pa + (rRhoSeawater * rGravity * rTipSubmergence_m);

(* Propeller Inflow Velocity and Oblique Inflow Angle *)
rAdvanceSpeed_ms := rVesselSpeed_knots * 0.514444 * (1.0 - rWakeFraction_w);
rInflowAngle_deg := rVotedAzimuthAngle_deg - rVesselDriftAngle_deg;
WHILE rInflowAngle_deg > 180.0 DO rInflowAngle_deg := rInflowAngle_deg - 360.0; END_WHILE;
WHILE rInflowAngle_deg < -180.0 DO rInflowAngle_deg := rInflowAngle_deg + 360.0; END_WHILE;

(* Blade Tip Resultant Inflow Velocity: V_tip = SQRT( V_axial^2 + (Pi * n * D)^2 ) *)
rTipSpeed_ms := SQRT((rAdvanceSpeed_ms * COS(rInflowAngle_deg * 0.0174533)) *
                     (rAdvanceSpeed_ms * COS(rInflowAngle_deg * 0.0174533)) +
                     (3.14159 * (rVotedShaftSpeed_RPM / 60.0) * rPropDiameter_m) *
                     (3.14159 * (rVotedShaftSpeed_RPM / 60.0) * rPropDiameter_m));
rTipSpeed_ms := MAX(1.0, rTipSpeed_ms);

(* Dimensionless Dynamic Pressure Head *)
rDynamicPressure_Pa := 0.5 * rRhoSeawater * rTipSpeed_ms * rTipSpeed_ms;

(* Real-Time Cavitation Inception Index (Thoma Number: Sigma = (P_stat - P_v) / (0.5 * rho * V_tip^2)) *)
rCavitationIndex_Sigma := (rStaticPressureTip_Pa - rVaporPressure_Pa) / rDynamicPressure_Pa;

(* Propeller Thrust Loading Coefficient: C_T = Thrust / (0.5 * rho * A_disk * V_advance^2) *)
rThrustLoading_CT := (rThrustDemand_kN * 1000.0) /
                     (0.5 * rRhoSeawater * rPropDiskArea_m2 * MAX(4.0, rAdvanceSpeed_ms * rAdvanceSpeed_ms));

(* Critical Cavitation Inception Boundary Function (Burrill-Keller Parametric Criterion) *)
rCriticalSigma := 0.35 + (0.12 * SQRT(MAX(0.01, rThrustLoading_CT))) + (0.00015 * rInflowAngle_deg * rInflowAngle_deg);

(* Headroom Margin & Risk Factor *)
rCavitationMargin_pct := ((rCavitationIndex_Sigma - rCriticalSigma) / MAX(0.01, rCriticalSigma)) * 100.0;

IF rCavitationMargin_pct < 0.0 THEN
    (* Direct Inception: Negative margin implies operating below vapor inception line *)
    rCavitationRiskFactor := MIN(1.0, (ABS(rCavitationMargin_pct) / 50.0) + (0.3 * rAcousticCavitationScore));
    bCavitationActive := TRUE;
    wAlarmWord := wAlarmWord OR 16#0200; (* Bit 9: Cavitation Limit Exceeded *)
ELSE
    rCavitationRiskFactor := MAX(0.0, (1.0 - (rCavitationMargin_pct / 100.0)) * 0.4 + (0.6 * rAcousticCavitationScore));
    bCavitationActive := (rAcousticCavitationScore > 0.4);
    IF NOT bCavitationActive THEN
        wAlarmWord := wAlarmWord AND 16#FDFF;
    END_IF;
END_IF;

(* -----------------------------------------------------------------------------
   PHASE 4: HYDRAULIC STEERING POWER UNIT (HPU) HEALTH MONITORING
   ----------------------------------------------------------------------------- *)
bHydraulicHealthy_A := (rHydraulicPressure_A_bar >= 160.0);
bHydraulicHealthy_B := (rHydraulicPressure_B_bar >= 160.0);

IF (NOT bHydraulicHealthy_A) AND (NOT bHydraulicHealthy_B) THEN
    wAlarmWord := wAlarmWord OR 16#0400; (* Bit 10: Total Steering Hydraulic Failure *)
    rMaxSlewRate_deg_s := 0.5;
    bDegradedMode := TRUE;
ELSIF (NOT bHydraulicHealthy_A) OR (NOT bHydraulicHealthy_B) THEN
    wAlarmWord := wAlarmWord OR 16#0800; (* Bit 11: Single Hydraulic Bank Degraded *)
    rMaxSlewRate_deg_s := 4.0;           (* Slew rate de-rated to 50% capacity *)
    bDegradedMode := TRUE;
ELSE
    wAlarmWord := wAlarmWord AND 16#F3FF;
    rMaxSlewRate_deg_s := 8.5;           (* Full high-speed steering dynamic response *)
    bDegradedMode := FALSE;
END_IF;

(* -----------------------------------------------------------------------------
   PHASE 5: MULTI-STAGE CYBER-PHYSICAL STATE MACHINE
   ----------------------------------------------------------------------------- *)
CASE iOperatingState OF

    0: (* STATE 0: INITIALIZATION & TMR STARTUP SYNC *)
        bSystemReady := FALSE;
        rShaftSpeedCommand_RPM := 0.0;
        rFilteredRPMCmd := 0.0;
        rFilteredAzimuthCmd_deg := rVotedAzimuthAngle_deg;
        rStateTimer_s := rStateTimer_s + rCycleTime_s;

        IF (rStateTimer_s > 2.0) AND bEnable AND bEStop THEN
            rStateTimer_s := 0.0;
            iOperatingState := 10; (* Proceed to TMR qualification check *)
        END_IF;

    10: (* STATE 10: TMR SENSOR VALIDATION & HYDRAULIC PRESSURE HEAD QUALIFICATION *)
        bSystemReady := FALSE;
        rStateTimer_s := rStateTimer_s + rCycleTime_s;

        (* Validate sensor health and hydraulic baseline pressure *)
        IF (NOT bSpeedSensorFault_A OR NOT bSpeedSensorFault_B) AND
           (NOT bAngleSensorFault_A OR NOT bAngleSensorFault_B) AND
           (bHydraulicHealthy_A OR bHydraulicHealthy_B) THEN
            rStateTimer_s := 0.0;
            IF rVesselSpeed_knots > 6.0 THEN
                iOperatingState := 30; (* Direct enter transit cruise *)
            ELSE
                iOperatingState := 20; (* Enter dynamic positioning vectoring *)
            END_IF;
        ELSIF rStateTimer_s > 5.0 THEN
            (* Timed out waiting for sensors to stabilize *)
            iOperatingState := 60; (* Sensor fallback hold *)
        END_IF;

    20: (* STATE 20: UNRESTRICTED DYNAMIC POSITIONING (DP) 360-DEG VECTORING *)
        bSystemReady := TRUE;

        (* Constrain Azimuth Slew Dynamics based on Cavitation Inception Protection *)
        IF bCavitationActive OR (rCavitationRiskFactor > 0.60) THEN
            iOperatingState := 40; (* Engage active cavitation mitigation *)
        ELSIF (NOT bHydraulicHealthy_A) OR (NOT bHydraulicHealthy_B) THEN
            iOperatingState := 50; (* Transition to degraded hydraulic steering *)
        ELSIF rVesselSpeed_knots > 8.0 THEN
            iOperatingState := 30; (* High speed transit regime *)
        ELSE
            (* Compute rate-limited azimuth vectoring command *)
            rSlewDelta := rAzimuthDemand_deg - rFilteredAzimuthCmd_deg;
            WHILE rSlewDelta > 180.0 DO rSlewDelta := rSlewDelta - 360.0; END_WHILE;
            WHILE rSlewDelta < -180.0 DO rSlewDelta := rSlewDelta + 360.0; END_WHILE;

            IF ABS(rSlewDelta) > (rMaxSlewRate_deg_s * rCycleTime_s) THEN
                IF rSlewDelta > 0.0 THEN
                    rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg + (rMaxSlewRate_deg_s * rCycleTime_s);
                ELSE
                    rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg - (rMaxSlewRate_deg_s * rCycleTime_s);
                END_IF;
            ELSE
                rFilteredAzimuthCmd_deg := rAzimuthDemand_deg;
            END_IF;

            (* Wrap filtered azimuth to [-180..+180] *)
            WHILE rFilteredAzimuthCmd_deg > 180.0 DO rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg - 360.0; END_WHILE;
            WHILE rFilteredAzimuthCmd_deg < -180.0 DO rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg + 360.0; END_WHILE;

            (* Modulate Shaft RPM according to thrust demand: Thrust proportional to n^2 *)
            rFilteredRPMCmd := SQRT(MAX(0.0, (rThrustDemand_kN * 1000.0) / 24.5));
            rFilteredRPMCmd := MIN(220.0, rFilteredRPMCmd);
        END_IF;

    30: (* STATE 30: TRANSIT CRUISE MODE (HIGH ADVANCE VELOCITY & RUDDER VECTORING) *)
        bSystemReady := TRUE;

        (* In transit mode, limit azimuth slewing range to +/- 35.0 deg to prevent hull broaching *)
        IF rAzimuthDemand_deg > 35.0 THEN
            rFilteredAzimuthCmd_deg := 35.0;
        ELSIF rAzimuthDemand_deg < -35.0 THEN
            rFilteredAzimuthCmd_deg := -35.0;
        ELSE
            rFilteredAzimuthCmd_deg := rAzimuthDemand_deg;
        END_IF;

        (* Advance ratio J = Va / (n * D) calculations *)
        rKT_AdvanceRatio := rAdvanceSpeed_ms / (MAX(0.1, (rVotedShaftSpeed_RPM / 60.0) * rPropDiameter_m));

        (* Throttle RPM Setpoint modulated for transit fuel economy and cavitation boundary *)
        rFilteredRPMCmd := MIN(220.0, SQRT(MAX(0.0, (rThrustDemand_kN * 1000.0) / 21.0)));

        IF bCavitationActive THEN
            iOperatingState := 40;
        ELSIF rVesselSpeed_knots < 5.0 THEN
            iOperatingState := 20;
        END_IF;

    40: (* STATE 40: ACTIVE CAVITATION INCEPTION LIMIT MITIGATION *)
        bSystemReady := TRUE;

        (* Constrain azimuth slew rate to 2.0 deg/s to suppress blade cross-flow separation *)
        rSlewDelta := rAzimuthDemand_deg - rFilteredAzimuthCmd_deg;
        WHILE rSlewDelta > 180.0 DO rSlewDelta := rSlewDelta - 360.0; END_WHILE;
        WHILE rSlewDelta < -180.0 DO rSlewDelta := rSlewDelta + 360.0; END_WHILE;

        IF ABS(rSlewDelta) > (2.0 * rCycleTime_s) THEN
            IF rSlewDelta > 0.0 THEN
                rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg + (2.0 * rCycleTime_s);
            ELSE
                rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg - (2.0 * rCycleTime_s);
            END_IF;
        ELSE
            rFilteredAzimuthCmd_deg := rAzimuthDemand_deg;
        END_IF;

        (* De-rate shaft rotational speed dynamically to restore cavitation safety margin *)
        rFilteredRPMCmd := rFilteredRPMCmd - (15.0 * rCavitationRiskFactor * rCycleTime_s * 10.0);
        rFilteredRPMCmd := MAX(40.0, rFilteredRPMCmd);

        (* Check if cavitation has ceased and safety margin restored above +15% *)
        IF (rCavitationMargin_pct > 15.0) AND (rAcousticCavitationScore < 0.15) THEN
            rStateTimer_s := rStateTimer_s + rCycleTime_s;
            IF rStateTimer_s > 3.0 THEN
                rStateTimer_s := 0.0;
                bCavitationActive := FALSE;
                IF rVesselSpeed_knots > 7.0 THEN
                    iOperatingState := 30;
                ELSE
                    iOperatingState := 20;
                END_IF;
            END_IF;
        ELSE
            rStateTimer_s := 0.0;
        END_IF;

    50: (* STATE 50: DEGRADED HYDRAULIC STEERING (SINGLE PUMP OPERATIONAL) *)
        bSystemReady := TRUE;
        bDegradedMode := TRUE;

        (* Apply half-rate slew clamp: 4.0 deg/s *)
        rSlewDelta := rAzimuthDemand_deg - rFilteredAzimuthCmd_deg;
        WHILE rSlewDelta > 180.0 DO rSlewDelta := rSlewDelta - 360.0; END_WHILE;
        WHILE rSlewDelta < -180.0 DO rSlewDelta := rSlewDelta + 360.0; END_WHILE;

        IF ABS(rSlewDelta) > (rMaxSlewRate_deg_s * rCycleTime_s) THEN
            IF rSlewDelta > 0.0 THEN
                rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg + (rMaxSlewRate_deg_s * rCycleTime_s);
            ELSE
                rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg - (rMaxSlewRate_deg_s * rCycleTime_s);
            END_IF;
        ELSE
            rFilteredAzimuthCmd_deg := rAzimuthDemand_deg;
        END_IF;

        (* Maintain RPM setpoint within nominal bounds *)
        rFilteredRPMCmd := MIN(180.0, SQRT(MAX(0.0, (rThrustDemand_kN * 1000.0) / 24.5)));

        (* Check if full hydraulic pressure has returned *)
        IF bHydraulicHealthy_A AND bHydraulicHealthy_B THEN
            iOperatingState := 20;
        END_IF;

    60: (* STATE 60: SENSOR DISPARITY FAIL-SAFE HOLD *)
        bSystemReady := FALSE;
        bDegradedMode := TRUE;
        (* Maintain current azimuth position, gently ramp shaft speed to safe idling 30 RPM *)
        IF rFilteredRPMCmd > 30.0 THEN
            rFilteredRPMCmd := rFilteredRPMCmd - (10.0 * rCycleTime_s);
        END_IF;

        IF (NOT bSpeedSensorFault_A OR NOT bSpeedSensorFault_B) AND
           (NOT bAngleSensorFault_A OR NOT bAngleSensorFault_B) THEN
            iOperatingState := 10; (* Recovered *)
        END_IF;

    99: (* STATE 99: HARDWARE EMERGENCY TRIP / PARK / SHUTDOWN *)
        bSystemReady := FALSE;
        rFilteredRPMCmd := 0.0;

        (* Slew azimuth to longitudinal 0.0 deg centerline for hydrodynamic streamlining *)
        rSlewDelta := 0.0 - rFilteredAzimuthCmd_deg;
        WHILE rSlewDelta > 180.0 DO rSlewDelta := rSlewDelta - 360.0; END_WHILE;
        WHILE rSlewDelta < -180.0 DO rSlewDelta := rSlewDelta + 360.0; END_WHILE;

        IF ABS(rSlewDelta) > (3.0 * rCycleTime_s) THEN
            IF rSlewDelta > 0.0 THEN
                rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg + (3.0 * rCycleTime_s);
            ELSE
                rFilteredAzimuthCmd_deg := rFilteredAzimuthCmd_deg - (3.0 * rCycleTime_s);
            END_IF;
        ELSE
            rFilteredAzimuthCmd_deg := 0.0;
        END_IF;

        IF bEnable AND bEStop AND (wAlarmWord = 16#0000) THEN
            iOperatingState := 0; (* Reset to init *)
        END_IF;

END_CASE;

(* -----------------------------------------------------------------------------
   PHASE 6: OUTPUT DEMAND ASSIGNMENT & DELIVERED THRUST ESTIMATOR
   ----------------------------------------------------------------------------- *)
rShaftSpeedCommand_RPM   := rFilteredRPMCmd;
rAzimuthAngleCommand_deg := rFilteredAzimuthCmd_deg;

(* Hydrodynamic Thrust Output Estimation via Open Water Characteristics *)
(* T = rho * n^2 * D^4 * Kt *)
rEstimatedKT := 0.48 - (0.35 * MAX(0.0, rAdvanceSpeed_ms / MAX(0.1, (rVotedShaftSpeed_RPM / 60.0) * rPropDiameter_m)));
rDeliveredThrust_kN := (rRhoSeawater *
                       ((rVotedShaftSpeed_RPM / 60.0) * (rVotedShaftSpeed_RPM / 60.0)) *
                       (rPropDiameter_m * rPropDiameter_m * rPropDiameter_m * rPropDiameter_m) *
                       MAX(0.01, rEstimatedKT)) / 1000.0;

(* Pack System Status Word *)
wSystemStatusWord.0 := bSystemReady;
wSystemStatusWord.1 := bCavitationActive;
wSystemStatusWord.2 := bDegradedMode;
wSystemStatusWord.3 := bHydraulicHealthy_A;
wSystemStatusWord.4 := bHydraulicHealthy_B;
wSystemStatusWord.5 := (iOperatingState = 20); (* DP Mode *)
wSystemStatusWord.6 := (iOperatingState = 30); (* Transit Mode *)
wSystemStatusWord.7 := (iOperatingState = 40); (* Mitigation Mode *)

END_FUNCTION_BLOCK
